package demo

import demo.app.App
import io.github.shijianjs.ktjs.oopreact.generated.initializeOopReact
import react.dom.client.createRoot
import web.dom.ElementId
import web.dom.document

/**
 * Entry point of the demo page.
 *
 * `initializeOopReact()` is the one statement the annotation model needs: it registers every
 * annotated class of this module and patches its render methods. It is generated by
 * `ktjs-oop-react-ksp` at build time — Kotlin/JS has neither a class-definition hook nor runtime
 * annotation reflection, so this call replaces both.
 *
 * The rest is exactly one React call: the whole object graph starts at `App`, and `root()` is the
 * only element React ever sees.
 */
fun main() {
    initializeOopReact()

    val container = document.getElementById(ElementId("root"))
        ?: error("The page has no <div id=\"root\">.")

    createRoot(container).render(App().root())
}
